-- MyLabs • Catálogo global de exercícios (PT-BR). Imagens: free-exercise-db (domínio público) via jsDelivr.
insert into public.exercises (slug, name_pt, muscle_group, secondary_muscles, equipment, level, instructions_pt, frame_urls)
select v.slug, v.name_pt, v.grp, v.sec, v.equip, v.lvl, v.steps,
  array[
    'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/' || v.slug || '/0.jpg',
    'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/' || v.slug || '/1.jpg']
from (values
-- PEITO
('Barbell_Bench_Press_-_Medium_Grip','Supino reto com barra','peito',array['triceps','ombros'],'Barra','iniciante',array['Deite no banco com os pés firmes no chão e as escápulas retraídas.','Desça a barra de forma controlada até tocar a parte média do peito.','Empurre a barra para cima até estender os cotovelos, sem tirar o quadril do banco.']),
('Dumbbell_Bench_Press','Supino reto com halteres','peito',array['triceps','ombros'],'Halteres','iniciante',array['Deite no banco segurando um haltere em cada mão na altura do peito.','Empurre os halteres para cima até quase estender os cotovelos.','Desça devagar até sentir o alongamento do peitoral.']),
('Incline_Dumbbell_Press','Supino inclinado com halteres','peito',array['ombros','triceps'],'Halteres','iniciante',array['Ajuste o banco entre 30° e 45° e deite-se com os halteres ao lado do peito.','Empurre os halteres para cima, aproximando-os no topo.','Desça controlando o movimento por cerca de 3 segundos.']),
('Decline_Barbell_Bench_Press','Supino declinado com barra','peito',array['triceps'],'Barra','iniciante',array['Prenda os pés no banco declinado e retire a barra do suporte.','Desça a barra até a parte inferior do peito.','Empurre até a extensão dos cotovelos mantendo os punhos alinhados.']),
('Leverage_Chest_Press','Supino na máquina','peito',array['triceps','ombros'],'Máquina','iniciante',array['Ajuste o banco para que as pegadas fiquem na altura do meio do peito.','Empurre as manoplas à frente sem travar os cotovelos.','Retorne devagar, mantendo o peitoral contraído.']),
('Dumbbell_Flyes','Crucifixo reto com halteres','peito',array['ombros'],'Halteres','iniciante',array['Deite no banco com os halteres acima do peito e cotovelos levemente flexionados.','Abra os braços em arco até sentir o alongamento do peitoral.','Feche o movimento como se abraçasse uma árvore, sem bater os halteres.']),
('Cable_Crossover','Crossover na polia','peito',array['ombros'],'Polia','iniciante',array['Posicione-se entre as polias altas com o tronco levemente inclinado.','Puxe as manoplas para baixo e à frente até as mãos se encontrarem.','Retorne controlando a carga até abrir o peitoral.']),
('Incline_Cable_Flye','Crucifixo inclinado na polia','peito',array['ombros'],'Polia','intermediario',array['Deite em banco inclinado entre duas polias baixas.','Eleve as manoplas em arco até se encontrarem acima do peito.','Desça devagar mantendo os cotovelos levemente flexionados.']),
('Butterfly','Voador (peck deck)','peito',array['ombros'],'Máquina','iniciante',array['Sente-se com as costas apoiadas e os antebraços nas almofadas.','Una os braços à frente do peito contraindo o peitoral.','Retorne lentamente até alongar sem exagerar na amplitude.']),
('Pushups','Flexão de braço','peito',array['triceps','ombros','abdomen'],'Peso corporal','iniciante',array['Apoie mãos e pontas dos pés no chão, corpo alinhado como uma prancha.','Flexione os cotovelos até o peito quase tocar o solo.','Empurre o chão e volte à posição inicial sem arquear a lombar.']),
('Incline_Push-Up','Flexão inclinada','peito',array['triceps','ombros'],'Peso corporal','iniciante',array['Apoie as mãos em um banco ou superfície elevada.','Mantenha o corpo reto e flexione os cotovelos até o peito se aproximar do apoio.','Empurre de volta até estender os braços.']),
-- COSTAS
('Wide-Grip_Lat_Pulldown','Puxada frontal aberta','costas',array['biceps'],'Polia','iniciante',array['Sente-se, ajuste o apoio das coxas e segure a barra com pegada aberta.','Puxe a barra até a altura do queixo levando os cotovelos para baixo.','Retorne devagar até estender os braços, sem deixar os ombros subirem.']),
('Close-Grip_Front_Lat_Pulldown','Puxada frontal fechada','costas',array['biceps'],'Polia','iniciante',array['Use a pegada triângulo ou barra fechada e incline o tronco levemente para trás.','Puxe até a parte alta do peito mantendo o peito aberto.','Controle a subida até alongar totalmente o dorsal.']),
('Straight-Arm_Pulldown','Pulldown com braços estendidos','costas',array['triceps'],'Polia','iniciante',array['De pé diante da polia alta, segure a barra com braços quase estendidos.','Desça a barra em arco até as coxas contraindo o dorsal.','Retorne devagar mantendo os cotovelos levemente flexionados.']),
('Pullups','Barra fixa','costas',array['biceps','antebraco'],'Barra fixa','intermediario',array['Segure a barra com pegada pronada um pouco mais larga que os ombros.','Eleve o corpo até o queixo passar da barra, sem balançar.','Desça de forma controlada até estender os braços.']),
('Chin-Up','Barra fixa supinada','costas',array['biceps'],'Barra fixa','iniciante',array['Segure a barra com as palmas voltadas para você, na largura dos ombros.','Puxe o corpo até o queixo ultrapassar a barra.','Desça devagar até a extensão completa dos cotovelos.']),
('Seated_Cable_Rows','Remada sentada na polia','costas',array['biceps'],'Polia','iniciante',array['Sente-se com os joelhos levemente flexionados e a coluna neutra.','Puxe o triângulo até o abdômen aproximando as escápulas.','Retorne alongando as costas sem arredondar a lombar.']),
('Bent_Over_Barbell_Row','Remada curvada com barra','costas',array['biceps'],'Barra','iniciante',array['Incline o tronco a cerca de 45° com a coluna neutra e os joelhos semiflexionados.','Puxe a barra em direção ao umbigo levando os cotovelos para trás.','Desça com controle sem alterar a posição do tronco.']),
('One-Arm_Dumbbell_Row','Remada unilateral com halter','costas',array['biceps'],'Halteres','iniciante',array['Apoie um joelho e uma mão no banco com as costas paralelas ao chão.','Puxe o haltere até a lateral do abdômen, cotovelo junto ao corpo.','Desça devagar até alongar o dorsal.']),
('Bent_Over_Two-Dumbbell_Row','Remada curvada com halteres','costas',array['biceps'],'Halteres','iniciante',array['Segure um haltere em cada mão e incline o tronco mantendo a coluna reta.','Puxe os halteres em direção ao quadril.','Retorne devagar sem balançar o corpo.']),
('T-Bar_Row_with_Handle','Remada cavalinho','costas',array['biceps'],'Barra T','iniciante',array['Posicione-se sobre a barra T com o tronco inclinado e a coluna neutra.','Puxe a barra até o peito contraindo as costas.','Desça controlando o peso sem arredondar a coluna.']),
('Barbell_Deadlift','Levantamento terra','costas',array['gluteos','posterior','quadriceps'],'Barra','intermediario',array['Posicione a barra sobre o meio dos pés e segure com pegada na largura dos ombros.','Mantenha a coluna neutra e empurre o chão com os pés para levantar a barra.','Estenda quadris e joelhos juntos e desça a barra de forma controlada.']),
('Hyperextensions_Back_Extensions','Extensão lombar no banco','costas',array['gluteos','posterior'],'Banco romano','iniciante',array['Ajuste o apoio na altura do quadril e cruze os braços no peito.','Desça o tronco com a coluna reta até sentir alongar a parte posterior.','Suba até alinhar o corpo, sem hiperestender a lombar.']),
('Superman','Superman (lombar no solo)','costas',array['gluteos'],'Peso corporal','iniciante',array['Deite de bruços com braços estendidos à frente.','Eleve braços e pernas ao mesmo tempo contraindo lombar e glúteos.','Segure 1 a 2 segundos e desça devagar.']),
