('Dumbbell_Shoulder_Press','Desenvolvimento com halteres','ombros',array['triceps'],'Halteres','intermediario',array['Sentado, segure os halteres na altura das orelhas com as palmas à frente.','Empurre os halteres para cima até quase estender os cotovelos.','Desça de forma controlada até a altura das orelhas.']),
('Seated_Barbell_Military_Press','Desenvolvimento militar com barra','ombros',array['triceps'],'Barra','intermediario',array['Sentado, retire a barra do suporte na altura dos ombros.','Empurre a barra acima da cabeça com o abdômen firme.','Desça até a altura do queixo mantendo o tronco estável.']),
