('Seated_Calf_Raise','Panturrilha sentado','panturrilha',array[]::text[],'Máquina','iniciante',array['Sente-se com as almofadas sobre os joelhos e a ponta dos pés na plataforma.','Eleve os calcanhares contraindo as panturrilhas.','Desça com controle até alongar.']),
-- ABDÔMEN
('Crunches','Abdominal crunch','abdomen',array[]::text[],'Peso corporal','iniciante',array['Deite com os joelhos flexionados e as mãos junto à cabeça.','Eleve os ombros do chão contraindo o abdômen, sem puxar o pescoço.','Desça devagar sem relaxar totalmente.']),
('Reverse_Crunch','Abdominal infra (reverso)','abdomen',array[]::text[],'Peso corporal','iniciante',array['Deite de costas com os joelhos flexionados sobre o quadril.','Eleve o quadril do chão levando os joelhos ao peito.','Desça devagar sem balançar.']),
('Cable_Crunch','Abdominal na polia','abdomen',array[]::text[],'Polia','iniciante',array['Ajoelhe-se diante da polia alta segurando a corda junto à cabeça.','Flexione o tronco levando os cotovelos em direção aos joelhos.','Retorne devagar mantendo o abdômen contraído.']),
('Cable_Seated_Crunch','Abdominal sentado na polia','abdomen',array[]::text[],'Polia','iniciante',array['Sente-se segurando a manopla da polia junto ao peito.','Flexione o tronco para a frente contraindo o abdômen.','Retorne com controle.']),
('Plank','Prancha isométrica','abdomen',array['ombros'],'Peso corporal','iniciante',array['Apoie antebraços e pontas dos pés no chão.','Mantenha o corpo alinhado, abdômen e glúteos contraídos.','Sustente a posição pelo tempo indicado sem deixar o quadril cair.']),
('Side_Bridge','Prancha lateral','abdomen',array['ombros'],'Peso corporal','iniciante',array['Deite de lado apoiando o antebraço no chão.','Eleve o quadril alinhando o corpo da cabeça aos pés.','Sustente a posição e repita do outro lado.']),
('Russian_Twist','Rotação russa','abdomen',array[]::text[],'Peso corporal','intermediario',array['Sente-se com o tronco inclinado para trás e os pés elevados ou apoiados.','Gire o tronco de um lado ao outro tocando o chão ao lado do quadril.','Mantenha o abdômen contraído durante todo o movimento.']),
('Ab_Roller','Roda abdominal','abdomen',array['ombros'],'Roda abdominal','intermediario',array['Ajoelhe-se segurando a roda à frente do corpo.','Role para a frente mantendo o abdômen contraído e a lombar neutra.','Retorne puxando com o abdômen.']),
('Hanging_Leg_Raise','Elevação de pernas na barra','abdomen',array['antebraco'],'Barra fixa','avancado',array['Pendure-se na barra com os braços estendidos.','Eleve as pernas até o quadril ficar a 90° ou mais.','Desça devagar sem balançar o corpo.']),
('Air_Bike','Abdominal bicicleta','abdomen',array[]::text[],'Peso corporal','iniciante',array['Deite com as mãos atrás da cabeça e as pernas elevadas.','Leve o cotovelo ao joelho oposto alternando os lados.','Mantenha o movimento controlado, sem puxar o pescoço.']),
