('Mountain_Climbers','Escalador (mountain climber)','cardio',array['abdomen','ombros'],'Peso corporal','iniciante',array['Apoie as mãos no chão na posição de flexão.','Leve os joelhos alternadamente em direção ao peito em ritmo constante.','Mantenha o quadril baixo e o abdômen firme.']),
('Rope_Jumping','Pular corda','cardio',array['panturrilha'],'Corda','intermediario',array['Segure a corda com os cotovelos próximos ao corpo.','Salte de forma leve girando a corda com os punhos.','Aterrisse na ponta dos pés mantendo o ritmo.'])
